var datum, txt, New_Voltage;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - victron_TOP-Balancing.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// --->> MODE Umschaltung
on({ id: '0_userdata.0.Victron.TOP-Balancing' /* TOP-Balancing */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  // Spannung
  if ((obj.state ? obj.state.val : '')) {
    setState('javascript.0.Victron.TOP-StartV' /* TOP-StartV */, getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val, true);
    setState('mqtt.2.ioBroker.BAT_MaxChargeVoltage' /* ioBroker/BAT_MaxChargeVoltage */, (getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val + 0.2));
    setState('mqtt.1.ioBroker.ESS_MaxChargeVoltage' /* ioBroker/ESS_MaxChargeVoltage */, (getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val + 0.2));
    setState('0_userdata.0.Victron.DebugAktiv' /* DebugAktiv */, true, true);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['----------------------------------------------------','\n','TOP-Balancing/ START - Voltage auf (V): ',('' + getState('javascript.0.Victron.TOP-StartV').val)].join(''));
  } else {
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['TOP-Balancing/ ENDE - Spannung wird reduziert. ',getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val,'V'].join(''));
    }
  }
});
on({ id: [].concat(['alias.0.MP-ESS.DC-Voltage']).concat(['alias.0.MP-BAT.DC-Voltage']), change: 'ne' }, async (obj) => {
  if (getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val != getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val && getState('0_userdata.0.Victron.TOP-Balancing').val) {
    setState('mqtt.2.ioBroker.BAT_MaxChargeVoltage' /* ioBroker/BAT_MaxChargeVoltage */, parseFloat(getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val), true);
  }
});
schedule("*/30 * * * * *", async () => {
  if (getState('javascript.0.Victron.TOP-StartV').val != 0 && !getState('0_userdata.0.Victron.TOP-Balancing').val) {
    if (getState('alias.0.Gobel.Current').val <= 1) {
      setState('mqtt.1.ioBroker.ESS_MaxChargeVoltage' /* ioBroker/ESS_MaxChargeVoltage */, Math.round((Math.min(Math.max(getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val - 0.1, getState('javascript.0.Victron.TOP-StartV').val), getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val)) * 10) / 10);
      setState('mqtt.2.ioBroker.BAT_MaxChargeVoltage' /* ioBroker/BAT_MaxChargeVoltage */, Math.round((Math.min(Math.max(getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val - 0.1, getState('javascript.0.Victron.TOP-StartV').val), getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val)) * 10) / 10);
      if (getState('0_userdata.0.Victron.DebugAktiv').val) {
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'TOP-Balancing/ ENDE - Voltage zurück auf (V): ' + String(('' + getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val)));
      }
      console.debug(('TOP-StartV: ' + String(getState('javascript.0.Victron.TOP-StartV').val)));
      if (getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val <= getState('javascript.0.Victron.TOP-StartV').val) {
        if (getState('0_userdata.0.Victron.DebugAktiv').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['TOP-Balancing/ ENDE - Voltage zurück auf (V): ',('' + getState('javascript.0.Victron.TOP-StartV').val),'\n','----------------------------------------------------'].join(''));
          sendTo('telegram.0', 'send', {
            text: ('TOP-Balancing/ ENDE - Voltage zurück auf (V): ' + String(('' + getState('javascript.0.Victron.TOP-StartV').val))),
          });
        }
        setState('0_userdata.0.Victron.DebugAktiv' /* DebugAktiv */, false, true);
        setState('javascript.0.Victron.TOP-StartV' /* TOP-StartV */, 0, true);
      }
    } else {
      if (getState('0_userdata.0.Victron.DebugAktiv').val) {
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['TOP-Balancing/ ENDE - Spannung kann nicht reduziert werden, Strom zu hoch.',('' + getState('alias.0.Gobel.Current').val),'A'].join(''));
      }
    }
  }
});

// --->> Spannung regeln
schedule("*/10 * * * *", async () => {
  if (getState('0_userdata.0.Victron.TOP-Balancing').val) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['- VShunt: ',getState('alias.0.Gobel.Voltage_SmartShunt').val,', DiffV M: ',getState('alias.0.Gobel_Master.Gobe_Master_Diff_mV').val,', DiffV S1: ',getState('alias.0.Gobel_Slave1.Gobel_Slave1_Diff_mV').val,', DiffV S2: ',getState('alias.0.Gobel_Slave2.Gobel_Slave2_Diff_mV').val,', DiffV S3: ',getState('alias.0.Gobel_Slave3.Gobel_Slave3_Diff_mV').val,', Strom: ',getState('alias.0.Gobel.Current SmartShunt').val].join(''));
    // wenn der Strom unter xA ist, die Spannung
    // um 0,2V erhöhen und die
    // DiffV kleiner XmV
    if (getState('alias.0.Gobel.Current SmartShunt').val < 4 && (getState('alias.0.Gobel_Master.Gobe_Master_Diff_mV').val < 100) && (getState('alias.0.Gobel_Slave1.Gobel_Slave1_Diff_mV').val < 100) && (getState('alias.0.Gobel_Slave3.Gobel_Slave3_Diff_mV').val < 100) && (getState('alias.0.Gobel_Slave3.Gobel_Slave3_Diff_mV').val < 100)) {
      New_Voltage = Math.round((Math.min(Math.max(Math.round((getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val + 0.1) * 10) / 10, 48), getState('0_userdata.0.Victron.TOP-maxVoltage').val)) * 10) / 10;
      setState('mqtt.2.ioBroker.BAT_MaxChargeVoltage' /* ioBroker/BAT_MaxChargeVoltage */, New_Voltage);
      setState('mqtt.1.ioBroker.ESS_MaxChargeVoltage' /* ioBroker/ESS_MaxChargeVoltage */, New_Voltage);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['TOP-Balancing/ Charge Voltage auf ',('' + New_Voltage),'V eingestellt.'].join(''));
      sendTo('telegram.0', 'send', {
        text: (['TOP-Balancing/ Charge Voltage auf ',('' + New_Voltage),'V eingestellt.'].join('')),
      });
    }
  }
});

// --->> STOP - Entladung
schedule("*/10 * * * * *", async () => {
  if (getState('0_userdata.0.Victron.TOP-Balancing').val) {
    if (getState('alias.0.Gobel.Current SmartShunt').val < -20) {
      setState('0_userdata.0.Victron.TOP-Balancing' /* TOP-Balancing */, false);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'TOP-Balancing/ --- ENDE --- Abbruch durch neg. Strom');
      sendTo('telegram.0', 'send', {
        text: 'TOP-Balancing/ --- ENDE --- Abbruch durch neg. Strom',
      });
    }
  }
});

// --->> STOP - Fertig
schedule("*/30 * * * * *", async () => {
  if (getState('0_userdata.0.Victron.TOP-Balancing').val) {
    if (getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val >= getState('0_userdata.0.Victron.TOP-maxVoltage').val && (getState('alias.0.Gobel_Master.Gobe_Master_Diff_mV').val <= getState('0_userdata.0.Victron.TOP-DiffV-End').val) && (getState('alias.0.Gobel_Slave1.Gobel_Slave1_Diff_mV').val <= getState('0_userdata.0.Victron.TOP-DiffV-End').val) && (getState('alias.0.Gobel_Slave2.Gobel_Slave2_Diff_mV').val <= getState('0_userdata.0.Victron.TOP-DiffV-End').val) && (getState('alias.0.Gobel_Slave3.Gobel_Slave3_Diff_mV').val <= getState('0_userdata.0.Victron.TOP-DiffV-End').val)) {
      setState('0_userdata.0.Victron.TOP-Balancing' /* TOP-Balancing */, false);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'TOP-Balancing/ --- ENDE ---');
      sendTo('telegram.0', 'send', {
        text: 'TOP-Balancing/ --- ENDE ---',
      });
    }
  }
});


